before.lib/client.ex:
defmodule Client do
  @moduledoc "Clients for different endpoints must coexist in one VM."
  def new(endpoint), do: %{endpoint: endpoint}
  def endpoint(client), do: client.endpoint
end

after.lib/client.ex:
defmodule Client do
  @moduledoc "Clients for different endpoints must coexist in one VM."
  def new(endpoint) do
    Application.put_env(:review_fixture, :endpoint, endpoint)
    %{}
  end
  def endpoint(_client), do: Application.fetch_env!(:review_fixture, :endpoint)
end
